def transform(grid):
    """Connect successive occurrences of the non-background marker horizontally and vertically in color 3."""
    if not grid or not grid[0]:
        return [row[:] for row in grid]
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    markers = [v for v in counts if v != bg]
    if len(markers) != 1:
        return [row[:] for row in grid]
    marker = markers[0]
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r in range(h):
        pts = [c for c in range(w) if grid[r][c] == marker]
        for a, b in zip(pts, pts[1:]):
            for c in range(a + 1, b):
                out[r][c] = 3
    for c in range(w):
        pts = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(pts, pts[1:]):
            for r in range(a + 1, b):
                out[r][c] = 3
    return out
